 'ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A',
 'TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q',
 'AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E',
 'TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R',
 'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}

def translate(s):
    return ''.join(codon_table.get(s[i:i+3],'?') for i in range(0,len(s)-2,3))

# find ORFs: from ATG to stop, min length 100 codons
print("Long ORFs (>=99 aa, i.e., >=300 nt) in 6 frames:\n")
orfs=[]
for strand, s in [('+',seq), ('-',rc(seq))]:
    for frame in range(3):
        # find all ATG..stop
        i=frame
        while i < len(s)-2:
            if s[i:i+3]=='ATG':
                j=i
                while j < len(s)-2:
                    if codon_table.get(s[j:j+3])=='*':
                        break
                    j+=3
                if j-i >= 300:
                    orfs.append((strand,frame,i,j))
                i+=3
            else:
                i+=3
for strand,frame,i,j in sorted(orfs, key=lambda x:-(x[3]-x[2])):
    prot=translate(s=None or (seq[i:j] if strand=='+' else rc(seq)[i:j]))
    print(f"strand {strand} frame {frame} len {j-i} nt ({ (j-i)//3 } aa)  coords({strand}): {i+1}-{j+2}")
    print("   ", prot[:60], "..." if len(prot)>60 else "")
print("\nNone found" if not orfs else "")

with open('region.fasta') as f:
    lines = f.read().splitlines()
seq = ''.join(lines[1:]).upper()
n = len(seq)
comp = {'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return ''.join(comp[c] for c in reversed(s))

# 1. Direct repeats: k-mers length>=20 occurring >1
print("=== Exact repeats (k>=20) ===")
found=False
for k in [30,25,22,20]:
    seen={}
    for i in range(n-k+1):
        kmer=seq[i:i+k]
        seen.setdefault(kmer,[]).append(i+1)
    reps={kk:v for kk,v in seen.items() if len(v)>1}
    for kk,v in reps.items():
        print(f"len{k}: {kk} at {v}")
        found=True
    if reps: break
if not found: print("none >=20")

# 2. Inverted repeats (palindromes): find seq[i:i+k] whose revcomp occurs elsewhere
print("\n=== Inverted repeats (stem length >= 12) ===")
found=False
for k in [24,20,16,12]:
    seen={}
    for i in range(n-k+1):
        seen.setdefault(seq[i:i+k],[]).append(i+1)
    for i in range(n-k+1):
        kmer=seq[i:i+k]
        r=rc(kmer)
        if r in seen:
            for j in seen[r]:
                if j > i+k:  # non-overlapping-ish
                    print(f"len{k}: {i+1} FWD .. {j} RC-rev  stem={k}")
                    found=True
    if found: break
if not found: print("none")

